solution.solution.c:
#include <stdbool.h>
#include <stddef.h>

struct point { double x; double y; };
struct rect { struct point corner; double width; double height; };

double area(struct rect r)
{
    return r.width * r.height;
}

bool contains(struct rect r, struct point p)
{
    return p.x >= r.corner.x && p.x <= r.corner.x + r.width
        && p.y >= r.corner.y && p.y <= r.corner.y + r.height;
}

void scale(struct rect *r, double factor)
{
    r->width *= factor;
    r->height *= factor;
}

bool overlaps(const struct rect *a, const struct rect *b)
{
    return a->corner.x < b->corner.x + b->width && b->corner.x < a->corner.x + a->width
        && a->corner.y < b->corner.y + b->height && b->corner.y < a->corner.y + a->height;
}

struct rect bounding_box(const struct point *points, size_t count)
{
    double min_x = points[0].x, max_x = points[0].x;
    double min_y = points[0].y, max_y = points[0].y;
    for (size_t i = 1; i < count; i++) {
        if (points[i].x < min_x) min_x = points[i].x;
        if (points[i].x > max_x) max_x = points[i].x;
        if (points[i].y < min_y) min_y = points[i].y;
        if (points[i].y > max_y) max_y = points[i].y;
    }
    struct rect r = {{min_x, min_y}, max_x - min_x, max_y - min_y};
    return r;
}

unitTests:
TEST("area") { struct rect r = {{1, 1}, 3, 4}; CHECK_NEAR(area(r), 12.0, 1e-9); }
TEST("containing points") { struct rect r = {{0, 0}, 10, 5}; struct point in = {3, 2}, edge = {10, 5}, out = {11, 2}, below = {3, -0.5}; CHECK(contains(r, in)); CHECK(contains(r, edge)); CHECK(!contains(r, out)); CHECK(!contains(r, below)); }
TEST("scaling through a pointer") { struct rect r = {{2, 3}, 4, 5}; scale(&r, 2.5); CHECK_NEAR(r.width, 10.0, 1e-9); CHECK_NEAR(r.height, 12.5, 1e-9); CHECK_NEAR(r.corner.x, 2.0, 1e-9); CHECK_NEAR(r.corner.y, 3.0, 1e-9); }
TEST("overlapping") { struct rect a = {{0, 0}, 4, 4}, b = {{2, 2}, 4, 4}, c = {{4, 0}, 2, 2}, d = {{10, 10}, 1, 1}, inside = {{1, 1}, 1, 1}; CHECK(overlaps(&a, &b)); CHECK(overlaps(&b, &a)); CHECK(!overlaps(&a, &c)); CHECK(!overlaps(&a, &d)); CHECK(overlaps(&a, &inside)); }
TEST("a bounding box") { struct point pts[] = {{1, 5}, {-2, 3}, {4, -1}}; struct rect r = bounding_box(pts, 3); CHECK_NEAR(r.corner.x, -2.0, 1e-9); CHECK_NEAR(r.corner.y, -1.0, 1e-9); CHECK_NEAR(r.width, 6.0, 1e-9); CHECK_NEAR(r.height, 6.0, 1e-9); struct point one[] = {{7, 7}}; r = bounding_box(one, 1); CHECK_NEAR(r.width, 0.0, 1e-9); CHECK_NEAR(r.corner.x, 7.0, 1e-9); }

